<style>
.my-task-database{container:task-database/inline-size;min-width:0;color:var(--color-ev-ink);--tdb-muted:#526476}.my-task-database :where(h1,h2,p){margin:0}.my-task-database :where(div,a,form,td,th){min-width:0}
