.my-task-database .tdb-toolbar{display:flex;align-items:end;flex-wrap:wrap;gap:.65rem;padding-block:.8rem 1rem}.my-task-database .tdb-search{flex:1 1 12rem;display:flex;align-items:center;gap:.5rem;min-height:2.75rem;background:var(--color-ev-surface);border:1px solid var(--color-ev-border);border-radius:.45rem;padding:0 .65rem}.my-task-database .tdb-search>svg{color:var(--tdb-muted)}.my-task-database .tdb-search input{width:100%;min-width:0;padding:.55rem 0;background:transparent;border:0;font:inherit;font-size:.875rem;color:inherit;outline-offset:2px}.my-task-database .tdb-search:focus-within{border-color:var(--color-ev-primary)}.my-task-database .tdb-filter{flex:1 1 9rem;max-width:100%}.my-task-database .tdb-filter-event{flex:1.15 1 10rem}.my-task-database .tdb-filter label{display:block;font-size:var(--text-ev-interface);font-weight:600;color:var(--tdb-muted);margin-bottom:.25rem}.my-task-database .tdb-filter select{width:100%;max-width:100%;min-height:2.75rem;border:1px solid var(--color-ev-border);border-radius:.45rem;padding-block:.5rem;padding-inline-start:.7rem;background-color:var(--color-ev-surface);font:inherit;font-size:.8125rem;color:var(--color-ev-ink)}.my-task-database .tdb-toolbar>.ev-button{min-height:2.75rem}.my-task-database .tdb-toolbar select:has(option:checked:not([value=""]):not([value="deadline_asc"])){border-color:var(--color-ev-primary)}
