)}.my-task-database .tdb-action-cell>a{min-height:2.25rem;display:flex}
.my-task-database .tdb-pill{display:inline-flex;align-items:center;gap:.35rem;border-radius:.35rem;padding:.2rem .45rem;font-size:.75rem;line-height:1.5;font-weight:var(--font-weight-medium);max-width:100%;color:var(--color-ev-neutral-ink);background:var(--color-ev-neutral-soft)}.my-task-database .tdb-pill>span{width:.4rem;height:.4rem;flex:none;border-radius:50%;background:currentColor}.my-task-database .tdb-pill-in_progress{background:var(--color-ev-info-soft);color:var(--color-ev-info)}.my-task-database .tdb-pill-done{background:var(--color-ev-success-soft);color:var(--color-ev-success)}.my-task-database .tdb-status-menu{position:relative}.my-task-database .tdb-status-menu summary{display:flex;align-items:center;gap:.3rem;cursor:pointer;min-height:2.25rem;list-style:none;border-radius:.35rem}.my-task-database .tdb-status-menu summary::-webkit-details-marker{display:none}.my-task-database .tdb-status-menu summary>svg{flex:none;color:var(--tdb-muted)}.my-task-database .tdb-status-menu[open] summary>svg{transform:rotate(180deg)}
.my-task-database .tdb-status-panel{position:absolute;top:100%;left:0;right:auto;width:min(18rem,calc(100vw - 2rem));min-width:0;max-width:calc(100vw - 2rem);border:1px solid var(--color-ev-border);border-radius:.65rem;background:var(--color-ev-surface);padding:.85rem;margin:0;box-shadow:0 8px 24px #25334414;translate:var(--filter-offset,0px) 0;transform:none;z-index:40}.my-task-database .tdb-status-panel label{display:block;font-size:var(--text-ev-interface);font-weight:600;margin-bottom:.3rem}.my-task-database .tdb-status-panel select{width:100%;max-width:100%;min-height:2.75rem;font:inherit;font-size:.8125rem;border:1px solid var(--color-ev-border);background-color:var(--color-ev-surface);border-radius:.4rem;padding-block:.4rem;padding-inline-start:.7rem}.my-task-database .tdb-status-panel p{font-size:.75rem;line-height:1.6;color:var(--tdb-muted);margin-block:.4rem}.my-task-database .tdb-status-panel .ev-button{min-height:2.75rem;padding-inline:.5rem;font-size:.75rem}
.my-task-database .tdb-empty{display:flex;gap:.8rem;align-items:flex-start;padding:1.4rem .5rem;border-block:1px solid var(--color-ev-border)}.my-task-database .tdb-empty>svg{color:var(--tdb-muted)}.my-task-database .tdb-empty h2{font-size:var(--text-ev-section);font-weight:var(--ev-heading-weight);line-height:var(--ev-heading-leading);letter-spacing:var(--ev-heading-tracking);}.my-task-database .tdb-empty p{font-size:.875rem;color:var(--tdb-muted);line-height:1.7;margin-top:.3rem}.my-task-database .tdb-pagination{margin-top:1rem}
@container task-database (max-width:45rem){.my-task-database .tdb-table thead{position:absolute;width:1px;height:1px;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap}.my-task-database .tdb-table,.my-task-database .tdb-table tbody{display:block}.my-task-database .tdb-table colgroup{display:none}.my-task-database .tdb-table tr{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);padding:.55rem 0;gap:.25rem .6rem;border-bottom:1px solid var(--color-ev-border)}.my-task-database .tdb-table tbody :is(td,th){display:block;padding:.2rem .55rem;border:0}.my-task-database .tdb-name-cell{grid-column:1/-1}.my-task-database .tdb-table .tdb-status-cell{grid-column:1;grid-row:2}.my-task-database .tdb-status-menu{position:relative}.my-task-database .tdb-status-menu summary{min-height:2.75rem}.my-task-database .tdb-table .tdb-action-cell{grid-column:2;grid-row:2;display:flex;align-items:start;justify-content:flex-end;flex-wrap:wrap;gap:.25rem .6rem}.my-task-database .tdb-action-cell>a{min-height:2.75rem}.my-task-database .tdb-event-cell{grid-column:1;grid-row:3}.my-task-database .tdb-deadline-cell{grid-column:2;grid-row:3}.my-task-database .tdb-event-cell::before,.my-task-database .tdb-deadline-cell::before{content:attr(data-label);display:block;font-size:var(--text-ev-metadata);color:var(--tdb-muted)}.my-task-database .tdb-status-panel{padding:.85rem}.my-task-database .tdb-table-region{border-top:1px solid var(--color-ev-border)}}
